import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def make(last, first):
    return Student("id", last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbot", "Cara")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Abbot, Cara | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count(self):
        people = [make("Abbot", "Cara")]
        for count in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(people, count)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
